insert into public.cabins(name,subtitle,max_capacity,regular_price,discount,description,image,gallery,amenities,is_featured,display_order)
values
('Cedar & Still','The forest hideaway',2,260,30,'A cedar-clad hideaway where tall windows bring the forest into every room. A king bed, warm timber interiors, and a sheltered deck make this a quiet retreat for two. Cook a slow dinner in your own kitchen, then settle beside the wood-burning stove.','https://images.unsplash.com/photo-1723663561534-9b129f182785?auto=format&fit=crop&w=1400&q=85',array['https://images.unsplash.com/photo-1723663561534-9b129f182785?auto=format&fit=crop&w=1400&ar=1:1&q=85','https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1400&q=80'],array['Private deck','Fully equipped kitchen','Quality bed linens','Walk-in shower','Wood-burning stove','Wi-Fi','Coffee & tea','Dedicated parking'],true,1),
('The Moss House','A woodland sanctuary',4,340,0,'A considered woodland cabin with soft green interiors and room to share. Two restful bedrooms, an open-plan kitchen, and a generous outdoor table set the scene for long meals and unhurried mornings. Step outside and make the most of your own forest-facing deck.','https://images.unsplash.com/photo-1697462247934-47afc5541494?auto=format&fit=crop&w=1400&q=85',array['https://images.unsplash.com/photo-1697462247934-47afc5541494?auto=format&fit=crop&w=1400&ar=1:1&q=85','https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1400&q=80'],array['Private deck','Fully equipped kitchen','Quality bed linens','Walk-in shower','Wood-burning stove','Wi-Fi','Coffee & tea','Dedicated parking'],true,2),
('Willow on Water','The lakeside escape',2,310,25,'A compact lakeside-inspired cabin for mornings spent watching the light change. A king bedroom opens onto a quiet sitting room with a small library and a well-equipped kitchen. The covered terrace is made for coffee, conversation, and a little fresh air.','https://images.unsplash.com/photo-1749453841669-5661423f5bc6?auto=format&fit=crop&w=1400&q=85',array['https://images.unsplash.com/photo-1749453841669-5661423f5bc6?auto=format&fit=crop&w=1400&ar=1:1&q=85','https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1400&q=80'],array['Private deck','Fully equipped kitchen','Quality bed linens','Walk-in shower','Wood-burning stove','Wi-Fi','Coffee & tea','Dedicated parking'],true,3),
('The Larch Lodge','A gathering place',6,480,40,'A spacious timber lodge imagined for good company and shared meals. Three bedrooms offer room to retreat, while the generous living area brings everyone together around a stone fireplace. A full kitchen and broad dining table make staying in feel like the right plan.','https://images.unsplash.com/photo-1484382795892-6d20982be550?auto=format&fit=crop&w=1400&q=85',array['https://images.unsplash.com/photo-1484382795892-6d20982be550?auto=format&fit=crop&w=1400&ar=1:1&q=85','https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1400&q=80'],array['Private deck','Fully equipped kitchen','Quality bed linens','Walk-in shower','Wood-burning stove','Wi-Fi','Coffee & tea','Dedicated parking'],false,4),
('Fern & Field','The slow living cabin',4,360,0,'An airy A-frame with a bright living room and warm, natural finishes. A double bedroom and a cosy loft sleep four, with a reading nook tucked below the eaves. French doors lead to a private deck and a table for lingering breakfasts.','https://images.unsplash.com/photo-1758509362549-df81e9e779c5?auto=format&fit=crop&w=1400&q=85',array['https://images.unsplash.com/photo-1758509362549-df81e9e779c5?auto=format&fit=crop&w=1400&ar=1:1&q=85','https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1400&q=80'],array['Private deck','Fully equipped kitchen','Quality bed linens','Walk-in shower','Wood-burning stove','Wi-Fi','Coffee & tea','Dedicated parking'],false,5),
('Pinefall Retreat','Under the evergreens',4,390,35,'A secluded pine-forest-inspired cabin designed around a beautiful view. Two bedrooms, generous windows, and a deep sofa make it easy to spend the afternoon indoors. A private terrace extends the living space into the trees.','https://images.unsplash.com/photo-1777768785875-2294b91a7b1c?auto=format&fit=crop&w=1400&q=85',array['https://images.unsplash.com/photo-1777768785875-2294b91a7b1c?auto=format&fit=crop&w=1400&ar=1:1&q=85','https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1400&q=80'],array['Private deck','Fully equipped kitchen','Quality bed linens','Walk-in shower','Wood-burning stove','Wi-Fi','Coffee & tea','Dedicated parking'],false,6),
('Emberwood','For fireside evenings',6,520,50,'A warm, inviting lodge that puts gathering at its heart. Three bedrooms surround a generous open living space, with a stone hearth and kitchen for cooking together. End the day around the outdoor seating area as the forest settles into evening.','https://images.unsplash.com/photo-1769746484316-a9090d0a9690?auto=format&fit=crop&w=1400&q=85',array['https://images.unsplash.com/photo-1769746484316-a9090d0a9690?auto=format&fit=crop&w=1400&ar=1:1&q=85','https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1400&q=80'],array['Private deck','Fully equipped kitchen','Quality bed linens','Walk-in shower','Wood-burning stove','Wi-Fi','Coffee & tea','Dedicated parking'],false,7),
('The Quiet Summit','A wider horizon',8,680,60,'Our largest imagined escape, with four bedrooms and space for everyone to find their own corner. A large kitchen, broad windows, and a generous lounge bring light into the heart of the cabin. Take a book onto the deck and let the day unfold.','https://images.unsplash.com/photo-1641437123627-837979a33c39?auto=format&fit=crop&w=1400&q=85',array['https://images.unsplash.com/photo-1641437123627-837979a33c39?auto=format&fit=crop&w=1400&ar=1:1&q=85','https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1400&q=80'],array['Private deck','Fully equipped kitchen','Quality bed linens','Walk-in shower','Wood-burning stove','Wi-Fi','Coffee & tea','Dedicated parking'],false,8);
